# This code has been fully generated by an AI.

import random

import numpy as np
import pytest

from hebocon.config import Settings
from hebocon.game import Game, Item, RobotInput


@pytest.fixture
def cfg() -> Settings:
    return Settings(_env_file=None)


def robot(rid, pos, vel=(0, 0), inside=1.0, present=True, radius=40.0):
    pos = np.array(pos, np.float32)
    angles = np.linspace(0, 2 * np.pi, 20, endpoint=False)
    outline = (pos + radius * np.stack([np.cos(angles), np.sin(angles)], 1)).astype(np.float32)
    return RobotInput(rid, present, pos, np.array(vel, np.float32), radius, inside, outline)


def new_game(cfg) -> Game:
    return Game(cfg, [(1, "A"), (2, "B")], 0.0, random.Random(1))


def hp(game):
    return [round(p.hp, 3) for p in game.players]


def test_start_hp(cfg):
    assert hp(new_game(cfg)) == [100, 100]


def test_ringout_drains_after_grace(cfg):
    g = new_game(cfg)
    for k in range(1, 31):
        g.tick(k * 0.1, [robot(1, (500, 500), inside=0.2), robot(2, (200, 200))], False)
    # Erstes Tick bei 0.1 → 2.9 s draußen, 0.5 s Schonfrist → 2.4 s × 5 HP/s.
    assert hp(g) == [88, 100]


def test_ringout_stops_when_back(cfg):
    g = new_game(cfg)
    g.tick(0.1, [robot(1, (500, 500), inside=0.2), robot(2, (200, 200))], False)
    g.tick(0.4, [robot(1, (500, 500), inside=0.2), robot(2, (200, 200))], False)
    g.tick(5.0, [robot(1, (500, 500), inside=0.9), robot(2, (200, 200))], False)
    assert hp(g) == [100, 100]


def collide(g, v1, v2):
    g.tick(0.1, [robot(1, (400, 500), v1), robot(2, (600, 500), v2)], False)
    g.tick(0.2, [robot(1, (460, 500), v1), robot(2, (540, 500), v2)], True)


def test_faster_robot_deals_damage(cfg):
    g = new_game(cfg)
    collide(g, (300, 0), (0, 0))
    assert hp(g) == [100, 90]


def test_equal_speed_both_lose(cfg):
    g = new_game(cfg)
    collide(g, (200, 0), (-210, 0))
    assert hp(g) == [95, 95]


def test_slow_touch_no_damage(cfg):
    g = new_game(cfg)
    collide(g, (30, 0), (-20, 0))
    assert hp(g) == [100, 100]


def test_pushing_does_not_drain(cfg):
    g = new_game(cfg)
    collide(g, (300, 0), (0, 0))
    for k in range(3, 60):
        g.tick(k * 0.1, [robot(1, (470, 500), (300, 0)), robot(2, (530, 500), (300, 0))], True)
    assert hp(g) == [100, 90]


def test_collision_cooldown(cfg):
    g = new_game(cfg)
    collide(g, (300, 0), (0, 0))
    g.tick(0.3, [robot(1, (400, 500), (300, 0)), robot(2, (600, 500))], False)
    g.tick(0.4, [robot(1, (460, 500), (300, 0)), robot(2, (540, 500))], True)
    assert hp(g) == [100, 90]
    g.tick(1.5, [robot(1, (400, 500), (300, 0)), robot(2, (600, 500))], False)
    g.tick(1.6, [robot(1, (460, 500), (300, 0)), robot(2, (540, 500))], True)
    assert hp(g) == [100, 80]


def test_obstacle_hits_once_after_arming(cfg):
    g = new_game(cfg)
    g.items.append(Item(1, "obstacle", np.array([500, 500], np.float32), 60, 0.0, 8.0, 1.0))
    g.tick(0.5, [robot(1, (500, 500)), robot(2, (100, 100))], False)
    assert hp(g) == [100, 100] and g.items
    g.tick(1.1, [robot(1, (500, 500)), robot(2, (100, 100))], False)
    g.tick(1.2, [robot(1, (500, 500)), robot(2, (100, 100))], False)
    assert hp(g) == [70, 100] and not g.items


def test_powerup_heals_capped(cfg):
    g = new_game(cfg)
    g.players[0].hp = 90
    g.items.append(Item(1, "powerup", np.array([500, 500], np.float32), 45, 0.0, 10.0, 0.0))
    g.tick(0.1, [robot(1, (520, 500)), robot(2, (100, 100))], False)
    assert hp(g) == [100, 100] and not g.items


def test_items_expire(cfg):
    g = new_game(cfg)
    g.items.append(Item(1, "powerup", np.array([500, 500], np.float32), 45, 0.0, 10.0, 0.0))
    g.tick(10.5, [robot(1, (100, 100)), robot(2, (900, 900))], False)
    assert not g.items


def test_spawn_keeps_clear_of_robots(cfg):
    g = new_game(cfg)
    robots = [robot(1, (300, 500), radius=60), robot(2, (700, 500), radius=60)]
    for _ in range(20):
        g.items.clear()
        assert g.spawn("obstacle", 0.0, robots)
        item = g.items[0]
        assert all(np.linalg.norm(item.pos - r.pos) >= r.radius + item.radius for r in robots)


def test_spawn_respects_robot_outline(cfg):
    g = new_game(cfg)
    # Langer Roboter: Der Kreis um die Mitte wäre zu klein, nur der Umriss schützt die Enden.
    long = RobotInput(1, True, np.array([500, 500], np.float32), np.zeros(2, np.float32), 30.0, 1.0,
                      np.array([[100, 470], [900, 470], [900, 530], [100, 530]], np.float32))
    for _ in range(50):
        assert g.spawn("powerup", 0.0, [long])
    for item in g.items:
        assert not (100 - item.radius < item.pos[0] < 900 + item.radius
                    and 470 - item.radius < item.pos[1] < 530 + item.radius)


def test_spawn_avoids_unseen_robot(cfg):
    g = new_game(cfg)
    hidden = RobotInput(1, False, np.array([500, 500], np.float32), np.zeros(2, np.float32), 80.0, 1.0, None)
    for _ in range(15):
        assert g.spawn("obstacle", 0.0, [hidden])
    assert all(np.linalg.norm(i.pos - hidden.pos) >= hidden.radius + i.radius for i in g.items)


def test_rapid_spawns_without_limit(cfg):
    g = new_game(cfg)
    robots = [robot(1, (300, 500)), robot(2, (700, 500))]
    for _ in range(15):
        assert g.spawn("obstacle", 0.0, robots)
        assert g.spawn("powerup", 0.0, robots)
    assert len(g.items) == 30
    # Gleicher Zeitpunkt, trotzdem alle angenommen und ohne Überlappung untereinander.
    for a in g.items:
        assert 0 <= a.pos[0] - a.radius and a.pos[0] + a.radius <= 1000
        assert 0 <= a.pos[1] - a.radius and a.pos[1] + a.radius <= 1000
        for b in g.items:
            if a is not b:
                assert np.linalg.norm(a.pos - b.pos) >= a.radius + b.radius


def test_spawn_fails_without_room(cfg):
    g = Game(cfg, [(1, "A"), (2, "B")], 0.0, random.Random(1), size=(200.0, 200.0))
    assert not g.spawn("obstacle", 0.0, [robot(1, (100, 100), radius=90)])
    assert g.items == [] and not any(e["type"] == "spawn" for e in g.events)


def test_nothing_spawns_without_button(cfg):
    g = new_game(cfg)
    for k in range(1, 3000):
        g.tick(k * 0.1, [robot(1, (100, 100)), robot(2, (900, 900))], False)
    assert g.items == []
    assert not any(e["type"] == "spawn" for e in g.events)


def test_ko_ends_match(cfg):
    g = new_game(cfg)
    g.players[1].hp = 5
    collide(g, (300, 0), (0, 0))
    assert g.finished and g.winner == 1 and hp(g) == [100, 0]
    g.tick(5.0, [robot(1, (500, 500), inside=0.0), robot(2, (500, 500))], False)
    assert hp(g) == [100, 0]

def test_lost_at_edge_is_ko(cfg):
    g = new_game(cfg)
    g.tick(0.1, [robot(1, (20, 500), inside=0.3), robot(2, (500, 500))], False)
    lost = RobotInput(1, False, np.array([20, 500], np.float32), np.zeros(2, np.float32), 40.0, 0.0, None,
                      edge=True)
    g.tick(0.2, [lost, robot(2, (500, 500))], False)
    assert g.finished and g.winner == 2 and hp(g)[0] == 0
    assert [e["type"] for e in g.events][-2:] == ["ringout_ko", "ko"]


def test_lost_in_middle_drains(cfg):
    g = new_game(cfg)
    hidden = RobotInput(1, False, np.array([500, 500], np.float32), np.zeros(2, np.float32), 40.0, 1.0, None)
    for k in range(1, 31):
        g.tick(k * 0.1, [hidden, robot(2, (200, 200))], False)
    assert hp(g) == [88, 100] and not g.finished


def test_shrink_reaches_min_area_and_drains(cfg):
    g = new_game(cfg)
    assert g.zone(0.0) is None
    assert g.start_shrink(1.0) and not g.start_shrink(2.0)
    assert g.zone(1.0) == (0.0, 0.0, 1000.0, 1000.0)
    x0, y0, x1, y1 = g.zone(1.0 + 2 * cfg.shrink_duration_s)
    assert abs((x1 - x0) * (y1 - y0) / 1000.0**2 - cfg.shrink_min_area) < 1e-6
    # Roboter nah am Rand: nach dem Schrumpfen draußen, in der Mitte bleibt alles ruhig.
    t = 1.0 + cfg.shrink_duration_s
    for k in range(31):
        g.tick(t + k * 0.1, [robot(1, (100, 500)), robot(2, (500, 500))], False)
    assert hp(g) == [87.5, 100]


def test_spawn_stays_inside_zone(cfg):
    g = new_game(cfg)
    g.start_shrink(0.0)
    x0, y0, x1, y1 = g.zone(cfg.shrink_duration_s)
    for _ in range(5):
        assert g.spawn("powerup", cfg.shrink_duration_s, [])
        assert g.spawn("obstacle", cfg.shrink_duration_s, [])
    for item in g.items:
        x, y = item.pos
        r = item.radius
        assert x0 <= x - r and x + r <= x1 and y0 <= y - r and y + r <= y1


def test_spawn_during_shrink_stays_inside_until_expiry(cfg):
    g = new_game(cfg)
    g.start_shrink(0.0)
    for _ in range(10):
        assert g.spawn("obstacle", 1.0, [])
    for item in g.items:
        x0, y0, x1, y1 = g.zone(item.expires)
        x, y = item.pos
        r = item.radius
        assert x0 <= x - r and x + r <= x1 and y0 <= y - r and y + r <= y1


def test_zone_keeps_aspect_of_rectangular_arena(cfg):
    g = Game(cfg, [(1, "A"), (2, "B")], 0.0, random.Random(1), size=(1000.0, 500.0))
    g.start_shrink(0.0)
    x0, y0, x1, y1 = g.zone(cfg.shrink_duration_s)
    assert (x0 + x1) / 2 == 500.0 and (y0 + y1) / 2 == 250.0
    assert abs((x1 - x0) * (y1 - y0) / (1000.0 * 500.0) - cfg.shrink_min_area) < 1e-6

def charged_game(cfg):
    g = new_game(cfg)
    g.tick(0.1, [robot(1, (200, 500)), robot(2, (800, 500))], False)
    # Schaden durch einen Gegenstand lädt die Ulti von Roboter 1.
    g.player(1).hp, g.player(1).taken = 50.0, 50.0
    return g


def test_ulti_charges_by_damage_taken(cfg):
    g = new_game(cfg)
    g.items.append(Item(1, "obstacle", np.array([500, 500], np.float32), 60, 0, 99, 0))
    g.tick(0.1, [robot(1, (500, 500)), robot(2, (800, 500))], False)
    assert g.ulti_charge(g.player(1)) == pytest.approx(cfg.obstacle_damage / cfg.ulti_charge_hp)
    assert not g.ulti_ready(g.player(1))
    assert not g.fire_ulti(1, 0.2)


def test_ulti_hits_when_target_stays(cfg):
    g = charged_game(cfg)
    assert g.fire_ulti(1, 1.0)
    g.tick(1.5, [robot(1, (200, 500)), robot(2, (800, 500))], False)
    assert g.player(2).hp == 100
    g.tick(1.0 + cfg.ulti_aim_s, [robot(1, (200, 500)), robot(2, (800, 500))], False)
    assert g.player(2).hp == 100 - cfg.ulti_damage
    assert [e["hit"] for e in g.events if e["type"] == "ulti_fire"] == [True]


def test_ulti_misses_when_target_dodges(cfg):
    g = charged_game(cfg)
    assert g.fire_ulti(1, 1.0)
    g.tick(1.0 + cfg.ulti_aim_s, [robot(1, (200, 500)), robot(2, (800, 800))], False)
    assert g.player(2).hp == 100
    assert [e["hit"] for e in g.events if e["type"] == "ulti_fire"] == [False]


def test_ulti_only_once(cfg):
    g = charged_game(cfg)
    assert g.fire_ulti(1, 1.0)
    g.tick(3.0, [robot(1, (200, 500)), robot(2, (800, 500))], False)
    assert not g.fire_ulti(1, 4.0)


def test_ulti_cancelled_when_finished(cfg):
    g = charged_game(cfg)
    assert g.fire_ulti(1, 1.0)
    g.knockout(1, 1.1)
    assert g.shot is None
